class ContinualEvaluationPhasePlugin(StrategyPlugin):
    def __init__(self,
                 tracking_plugins: List[TrackerPluginMetric],
                 max_task_subset_size=None,
                 eval_stream=None, eval_stream_task_labels=None,
                 mb_update_freq=100,
                 num_workers=4, pin_memory=True, skip_unseen_tasks=True,
                 ):
        super().__init__()
        self.tracking_collector = TrackingCollector()

        for p in tracking_plugins:
            assert isinstance(p, TrackerPluginMetric)
        self.plugins = tracking_plugins

        self.max_task_subset_size = max_task_subset_size if max_task_subset_size > 0 else None
        self.eval_stream = eval_stream
        self.eval_stream_task_labels = eval_stream_task_labels
        if self.eval_stream and self.eval_stream_task_labels is None:
            self.eval_stream_task_labels = list(range(len(self.eval_stream)))

        self.mb_update_freq = mb_update_freq
        self.num_workers = num_workers
        self.pin_memory = pin_memory
        self.skip_unseen_tasks = skip_unseen_tasks

        self.seen_tasks = []
        self.subset_idxs = [None] * len(self.eval_stream)
        self.initial_step = False

    def before_training(self, strategy: 'BaseStrategy', **kwargs):
        strategy.tracking_collector = self.tracking_collector
        for p in self.plugins:
            p.init_tracking(strategy)

    def before_training_exp(self, strategy: 'BaseStrategy') -> 'MetricResult':
        exp_counter = strategy.clock.train_exp_counter
        self.seen_tasks.append(exp_counter)

    def before_training_iteration(self, strategy: 'BaseStrategy') -> 'MetricResult':
        self.set_subset_idxs()
        strategy.tracking_collector.is_tracking_iteration = (
                strategy.clock.train_epoch_iterations % self.mb_update_freq == 0
                or strategy.clock.train_epoch_iterations == len(strategy.dataloader))

        if self.tracking_collector.is_first_preupdate_step:
            self.continual_eval_phase(strategy)

        if self.tracking_collector.collect_features and strategy.tracking_collector.is_tracking_iteration:
            self._collect_exps_feats(strategy, self.eval_stream)

    def after_training_iteration(self, strategy: 'BaseStrategy') -> 'MetricResult':
        self.tracking_collector.is_first_preupdate_step = False
        if strategy.tracking_collector.is_tracking_iteration:
            self.continual_eval_phase(strategy)

    def continual_eval_phase(self, strategy):
        self.before_tracking(strategy)
        self.track(strategy, self.eval_stream)
        self.after_tracking(strategy)

    def before_tracking(self, strategy: 'BaseStrategy'):
        for p in self.plugins:
            p.before_tracking(strategy)

    def track(self, strategy, eval_stream):
        col = self.tracking_collector
        _prev_state, _prev_training_modes = self.get_strategy_state(strategy)
        for exp, task_label, subset_idxs in zip(eval_stream, self.eval_stream_task_labels, self.subset_idxs):
            if self.skip_unseen_tasks and task_label not in self.seen_tasks:
                continue

            strategy.optimizer.zero_grad()
            strategy.is_training = True
            strategy.model.eval()
            dataset = exp.dataset.eval()

            self.before_tracking_step(strategy)

            if col.forward_with_grad:
                col.loss, col.post_update_features = self.forward_data(
                    dataset, strategy, task_label, collect_feats=col.collect_features, subset_idxs=subset_idxs)
                col.loss.backward()
            else:
                with torch.no_grad():
                    col.loss, col.post_update_features = self.forward_data(
                        dataset, strategy, task_label, collect_feats=col.collect_features, subset_idxs=subset_idxs)

            self.after_tracking_step(strategy)

        self.restore_strategy_(strategy, _prev_state, _prev_training_modes)
        strategy.optimizer.zero_grad()

    @staticmethod
    def get_strategy_state(strategy):
        _prev_state = (
            strategy.experience,
            strategy.adapted_dataset,
            strategy.dataloader,
            strategy.is_training)
        _prev_model_training_modes = {}
        for name, layer in strategy.model.named_modules():
            _prev_model_training_modes[name] = layer.training
        return _prev_state, _prev_model_training_modes

    @staticmethod
    def restore_strategy_(strategy, prev_state, prev_training_modes):
        strategy.experience, strategy.adapted_dataset = prev_state[:2]
        strategy.dataloader = prev_state[2]
        strategy.is_training = prev_state[3]
        for name, layer in strategy.model.named_modules():
            prev_mode = prev_training_modes[name]
            layer.train(mode=prev_mode)

class TrackingCollector:
    def __init__(self):
        self.collect_features = False
        self.forward_with_grad = False
        self.pre_update_features: dict = {}
        self.post_update_features = None
        self.loss = None
        self.gradnorm = None
        self.current_tracking_task = None
        self.is_first_preupdate_step = True
        self.is_tracking_iteration = False
        self.x, self.y, self.task_id = None, None, None
        self.preds_batch = None

class TrackerPluginMetric(PluginMetric[TResult]):
    def __init__(self, name, metric, reset_at='iteration'):
        super().__init__()
        self._metric = metric
        self.name = name
        assert reset_at in {'iteration', 'never'}
        self._reset_at = reset_at

    def result(self, strategy=None):
        return self._metric.result()

    def init_tracking(self, strategy: 'BaseStrategy'):
        pass

    def before_tracking(self, strategy: 'BaseStrategy'):
        if self._reset_at == 'iteration':
            self.reset(strategy)

    def before_training_iteration(self, strategy: 'BaseStrategy') -> 'MetricResult':
        col: TrackingCollector = strategy.tracking_collector
        if col.is_first_preupdate_step:
            return self._package_result(strategy, x_pos=-1)

    def after_training_iteration(self, strategy: 'BaseStrategy') -> None:
        col: TrackingCollector = strategy.tracking_collector
        if col.is_tracking_iteration:
            return self._package_result(strategy)

    def _package_result(self, strategy: 'BaseStrategy', x_pos=None) -> 'MetricResult':
        metric_value = self.result(strategy)
        add_exp = False
        plot_x_position = strategy.clock.train_iterations if x_pos is None else x_pos
        if isinstance(metric_value, dict):
            metrics = []
            for k, v in metric_value.items():
                metric_name = get_metric_name(
                    self, strategy, add_experience=add_exp, add_task=k)
                metrics.append(MetricValue(self, metric_name, v, plot_x_position))
            return metrics
        else:
            metric_name = get_metric_name(self, strategy,
                                          add_experience=add_exp,
                                          add_task=True)
            return [MetricValue(self, metric_name, metric_value, plot_x_position)]

    def __str__(self):
        reset_map = {'iteration': 'MB', 'never': 'STREAM'}
        assert self._reset_at in reset_map
        return f"TRACK_{reset_map[self._reset_at]}_{self.name}"

class TaskTrackingMINAccuracyPluginMetric(TrackerPluginMetric[float]):
    def __init__(self):
        self._current_acc = Accuracy()
        self.min_acc_tasks: dict = defaultdict(lambda: float('inf'))
        super().__init__(name="acc_MIN", metric=self._current_acc, reset_at='iteration')

    def result(self, strategy=None) -> Dict[int, float]:
        return {task: min_acc for task, min_acc in self.min_acc_tasks.items()}

    def update(self, strategy):
        col: TrackingCollector = strategy.tracking_collector
        self._current_acc.update(col.preds_batch, col.y, task_labels=col.current_tracking_task)

    def update_acc_minimum(self, strategy):
        current_learning_task = strategy.clock.train_exp_counter
        current_acc_results: Dict[int, float] = self._current_acc.result()
        for task, task_result in current_acc_results.items():
            if task != current_learning_task:
                self.min_acc_tasks[task] = min(self.min_acc_tasks[task], task_result)

    def after_tracking_batch(self, strategy: 'BaseStrategy') -> None:
        self.update(strategy)

    def after_tracking_step(self, strategy: 'BaseStrategy'):
        self.update_acc_minimum(strategy)

class WCACCPluginMetric(TrackerPluginMetric[float]):
    def __init__(self, min_acc_plugin: TaskTrackingMINAccuracyPluginMetric):
        self._current_acc = Accuracy()
        self.min_acc_plugin = min_acc_plugin
        self.WCACC = None
        super().__init__(name="WCACC", metric=self._current_acc, reset_at='iteration')

    def result(self, strategy=None) -> dict:
        return {0: self.WCACC}

    def update(self, strategy):
        col: TrackingCollector = strategy.tracking_collector
        current_learning_task = strategy.clock.train_exp_counter
        if current_learning_task == col.current_tracking_task:
            self._current_acc.update(col.preds_batch, col.y, task_labels=col.current_tracking_task)

    def after_tracking_batch(self, strategy: 'BaseStrategy') -> None:
        self.update(strategy)

    def after_tracking_step(self, strategy: 'BaseStrategy'):
        self.update_WCACC(strategy)

    def update_WCACC(self, strategy: 'BaseStrategy'):
        avg_list = []
        col: TrackingCollector = strategy.tracking_collector
        current_learning_task = strategy.clock.train_exp_counter

        if current_learning_task != col.current_tracking_task:
            return

        current_learning_task_acc: float = self._current_acc.result()[current_learning_task]
        avg_list.append(current_learning_task_acc)

        min_acc_results: Dict[int, float] = self.min_acc_plugin.result()
        if len(min_acc_results) > 0:
            avg_list.extend([min_acc for task_id, min_acc in min_acc_results.items()
                             if task_id != current_learning_task])

        self.WCACC = torch.mean(torch.tensor(avg_list)).item()

class WindowedForgettingPluginMetric(TrackerPluginMetric[float]):
    def __init__(self, window_size=10):
        self.window_size = window_size
        self._current_acc = Accuracy()
        super().__init__(name=f"F{self.window_size}", metric=self._current_acc, reset_at='iteration')

        self.acc_window: Dict[int, deque] = defaultdict(deque)
        self.max_forgetting: Dict[int, float] = defaultdict(float)

    def reset(self, strategy) -> None:
        self._current_acc.reset()

    def result(self, strategy=None) -> Dict[int, float]:
        return self.max_forgetting

    def update_current_task_acc(self, strategy):
        col: TrackingCollector = strategy.tracking_collector
        self._current_acc.update(col.preds_batch, col.y, task_labels=col.current_tracking_task)

    def update_task_window(self, strategy):
        col: TrackingCollector = strategy.tracking_collector
        new_acc_dict: Dict[int, float] = self._current_acc.result(task_label=col.current_tracking_task)
        new_acc = new_acc_dict[col.current_tracking_task]

        task_acc_window = self.acc_window[col.current_tracking_task]
        task_acc_window.append(new_acc)
        if len(task_acc_window) > self.window_size:
            task_acc_window.popleft()

        self.max_forgetting[col.current_tracking_task] = max(self.max_forgetting[col.current_tracking_task],
                                                             self.max_consec_delta_from_window(task_acc_window))

    def max_consec_delta_from_window(self, window) -> float:
        if len(window) <= 1:
            return 0
        max_delta = float('-inf')
        max_found_acc = float('-inf')
        for idx, val in enumerate(window):
            if val < max_found_acc:
                continue
            max_found_acc = val
            for other_idx in range(idx + 1, len(window)):
                other_val = window[other_idx]
                delta = self.delta(val, other_val)

                if delta > max_delta:
                    max_delta = delta
        return max_delta

    @staticmethod
    def delta(first_val, next_val):
        return first_val - next_val

    def after_tracking_batch(self, strategy: 'BaseStrategy') -> None:
        self.update_current_task_acc(strategy)

    def after_tracking_step(self, strategy: 'BaseStrategy'):
        self.update_task_window(strategy)

class WindowedPlasticityPluginMetric(WindowedForgettingPluginMetric):
    def __init__(self, window_size):
        super().__init__(window_size)
        self.name = f"P{self.window_size}"

    @staticmethod
    def delta(first_val, next_val):
        return next_val - first_val

class TaskTrackingGradnormPluginMetric(TrackerPluginMetric[float]):
    def __init__(self):
        self._gradnorm_mean = Loss()
        super().__init__(name="gradnorm", metric=self._gradnorm_mean, reset_at='iteration')

    def update(self, strategy):
        col = strategy.tracking_collector
        gradnorm = get_grad_normL2(strategy.model)
        self._gradnorm_mean.update(torch.tensor(gradnorm), patterns=1, task_label=col.current_tracking_task)

    def init_tracking(self, strategy: 'BaseStrategy'):
        col = strategy.tracking_collector
        col.forward_with_grad = True

    def after_tracking_step(self, strategy: 'BaseStrategy'):
        self.update(strategy)

class TaskTrackingFeatureDriftPluginMetric(TrackerPluginMetric[float]):
    def __init__(self):
        self._featdrift = Loss()
        super().__init__(name="featdrift", metric=self._featdrift, reset_at='iteration')

        self._pre_update_feats = {} # Per task

    def update(self, strategy):
        col: TrackingCollector = strategy.tracking_collector
        if col.is_first_preupdate_step:
            return
        assert col.pre_update_features is not None
        assert col.post_update_features is not None
        featdrift = self.get_feat_delta(col.pre_update_features[col.current_tracking_task], col.post_update_features)
        self._featdrift.update(featdrift, patterns=1, task_label=col.current_tracking_task)

    def init_tracking(self, strategy: 'BaseStrategy') -> 'MetricResult':
        col: TrackingCollector = strategy.tracking_collector
        col.collect_features = True

    def after_tracking_step(self, strategy: 'BaseStrategy'):
        self.update(strategy)
        self._pre_update_feats = {} # Reset

    @staticmethod
    def get_feat_delta(f1_batch, f2_batch):
        return torch.mean(torch.sum((f1_batch - f2_batch) ** 2, dim=-1))

def get_grad_normL2(model, norm_type: float = 2):
    parameters = model.parameters()
    if isinstance(model.parameters(), torch.Tensor):
        parameters = [parameters]
    parameters = [p for p in parameters if p.grad is not None]
    if len(parameters) == 0:
        return None
    device = parameters[0].grad.device

    total_norm = torch.norm(torch.stack(
        [torch.norm(p.grad.detach(), norm_type).to(device) for p in parameters]), norm_type)
    return total_norm.item()

class ERStrategy(BaseStrategy):
    def __init__(self,
                 n_total_memories,
                 num_tasks,
                 model, optimizer, criterion=torch.nn.CrossEntropyLoss(reduction='none'),
                 record_stability_gradnorm: bool = False,
                 Lw_new=0.5,
                 new_data_mb_size: int = 1, train_epochs: int = 1,
                 eval_mb_size: int = None, device=None,
                 plugins: Optional[List[StrategyPlugin]] = None,
                 evaluator: EvaluationPlugin = default_logger, eval_every=-1,
                 ):
        criterion.reduction = 'none'
        assert criterion.reduction == 'none', "Must have per-sample losses available for ER."
        assert 0 <= Lw_new <= 1
        self.Lw_new = Lw_new
        self.record_stability_gradnorm = record_stability_gradnorm

        plug = ERPlugin(
            n_total_memories=n_total_memories,
            num_tasks=num_tasks,
        )
        if plugins is None:
            plugins = [plug]
        else:
            plugins = [plug] + plugins

        if isinstance(criterion, StrategyPlugin):
            plugins += [criterion]

        super().__init__(
            model, optimizer, criterion=criterion,
            train_mb_size=new_data_mb_size, train_epochs=train_epochs,
            eval_mb_size=eval_mb_size, device=device, plugins=plugins,
            evaluator=evaluator, eval_every=eval_every)

        self.loss_reg = None
        self.loss_new = None
        self.gradnorm_stab = None

    def training_epoch(self, **kwargs):

        for self.mbatch in self.dataloader:
            if self._stop_training:
                break

            self._unpack_minibatch()
            nb_new_samples = self.mb_x.shape[0]
            self._before_training_iteration(**kwargs)

            self.optimizer.zero_grad()
            self.loss = 0

            self._before_forward(**kwargs)
            self.mb_output = self.forward()
            self._after_forward(**kwargs)

            self.loss_batch = self.criterion()

            mb_with_replay = False
            self.loss_new = self.Lw_new * self.loss_batch[:nb_new_samples].mean()
            self.loss = self.loss_new

            if nb_samples > nb_new_samples:
                mb_with_replay = True
                self.loss_reg = (1 - self.Lw_new) * self.loss_batch[nb_new_samples:].mean()
                if self.record_stability_gradnorm:
                    self.get_stability_gradnorm(self.loss_reg)
                self.loss = self.loss_new + self.loss_reg

            self._before_backward(**kwargs)
            self.loss.backward()
            self._after_backward(**kwargs)

            self._before_update(**kwargs)
            self.optimizer.step()
            self._after_update(**kwargs)

            self._after_training_iteration(**kwargs)

    def get_stability_gradnorm(self, loss_stab):
        _prev_state, _prev_training_modes = ContinualEvaluationPhasePlugin.get_strategy_state(self)

        self.model.eval()

        loss_stab.backward(retain_graph=True)
        self.gradnorm_stab = get_grad_normL2(self.model)

        ContinualEvaluationPhasePlugin.restore_strategy_(self, _prev_state, _prev_training_modes)
        self.optimizer.zero_grad()

class GEMStandardPlugin(StrategyPlugin):
    def __init__(self, patterns_per_experience: int, memory_strength: float):
        super().__init__()

        self.patterns_per_experience = int(patterns_per_experience)
        self.memory_strength = memory_strength

        self.memory_x, self.memory_y, self.memory_tid = {}, {}, {}

        self.G = None
        self.gradnorm_stab = None

    def before_training_iteration(self, strategy, **kwargs):
        if strategy.clock.train_exp_counter > 0:
            G = []
            G_norms = []
            strategy.model.train()
            for t in range(strategy.clock.train_exp_counter):
                strategy.model.train()
                strategy.optimizer.zero_grad()
                xref = self.memory_x[t].to(strategy.device)
                yref = self.memory_y[t].to(strategy.device)
                out = avalanche_forward(strategy.model, xref,
                                        self.memory_tid[t])
                loss = strategy._criterion(out, yref)
                loss.backward()

                G.append(torch.cat([p.grad.flatten() if p.grad is not None
                                    else torch.zeros(p.numel(),
                                                     device=strategy.device)
                                    for p in strategy.model.parameters()],
                                   dim=0))

                g_norm = get_grad_normL2(strategy.model)
                G_norms.append(g_norm)

            self.G = torch.stack(G)
            self.avg_gradnorm_G = torch.tensor(G_norms).mean()
            strategy.avg_gradnorm_G = self.avg_gradnorm_G

    @torch.no_grad()
    def after_backward(self, strategy, **kwargs):
        if strategy.clock.train_exp_counter > 0:
            g = torch.cat([p.grad.flatten() if p.grad is not None
                           else torch.zeros(p.numel(), device=strategy.device)
                           for p in strategy.model.parameters()], dim=0)

            to_project = (torch.mv(self.G, g) < 0).any()
        else:
            to_project = False

        self.gradnorm_stab = 0
        if to_project:
            g_tilde = self.solve_quadprog(g).to(strategy.device)

            num_pars = 0
            for p in strategy.model.parameters():
                curr_pars = p.numel()
                if p.grad is not None:
                    p.grad.copy_(
                        g_tilde[num_pars:num_pars + curr_pars].view(p.size()))
                num_pars += curr_pars

            assert num_pars == g_tilde.numel(), "Error in projecting gradient"

            g_stab = g_tilde - g
            self.gradnorm_stab = torch.norm(g_stab).item()

        strategy.gradnorm_stab = float(self.gradnorm_stab)

class LwFStandardPlugin(StrategyPlugin):
    def __init__(self, alpha=1, temperature=2):
        super().__init__()

        self.alpha = alpha
        self.temperature = temperature
        self.prev_model = None

        self.prev_classes = {'0': set()}

    def _distillation_loss(self, out, prev_out, active_units):
        au = list(active_units)
        log_p = torch.log_softmax(out / self.temperature, dim=1)[:, au]
        q = torch.softmax(prev_out / self.temperature, dim=1)[:, au]
        res = torch.nn.functional.kl_div(log_p, q, reduction='batchmean')
        return res

    def penalty(self, out, x, alpha, curr_model):
        if self.prev_model is None:
            return 0
        else:
            with torch.no_grad():
                if isinstance(self.prev_model, MultiTaskModule):
                    y_prev = avalanche_forward(self.prev_model, x, None)
                    y_curr = avalanche_forward(curr_model, x, None)
                else:
                    y_prev = {'0': self.prev_model(x)}
                    y_curr = {'0': out}

            dist_loss = 0
            for task_id in y_prev.keys():
                if task_id in self.prev_classes:
                    yp = y_prev[task_id]
                    yc = y_curr[task_id]
                    au = self.prev_classes[task_id]
                    dist_loss += self._distillation_loss(yc, yp, au)
            return alpha * dist_loss

    def before_backward(self, strategy, **kwargs):
        if strategy.clock.train_exp_iterations == 0:
            penalty = 0
        else:
            alpha = self.alpha[strategy.clock.train_exp_counter] \
                if isinstance(self.alpha, (list, tuple)) else self.alpha
            penalty = self.penalty(strategy.mb_output, strategy.mb_x, alpha,
                                   strategy.model)

        self.get_stability_gradnorm(strategy, penalty)

        strategy.loss_new = strategy.loss
        strategy.loss_reg = float(penalty)
        strategy.loss += penalty

    def get_stability_gradnorm(self, strategy, loss_stab):
        if not torch.is_tensor(loss_stab):
            strategy.gradnorm_stab = torch.tensor(0, dtype=torch.float)
            return
        _prev_state, _prev_training_modes = ContinualEvaluationPhasePlugin.get_strategy_state(strategy)

        strategy.model.eval()

        loss_stab.backward(retain_graph=True)
        strategy.gradnorm_stab = get_grad_normL2(strategy.model)

        ContinualEvaluationPhasePlugin.restore_strategy_(strategy, _prev_state, _prev_training_modes)
        strategy.optimizer.zero_grad()

class EWCStandardPlugin(StrategyPlugin):
    def __init__(self, iw_strength: float, mode='online', keep_importance_data=False):
        super().__init__()
        assert mode == 'separate' or mode == 'online',
            'Mode must be separate or online.'
        self.iw_strength = iw_strength
        self.mode = mode
        if self.mode == 'separate':
            self.keep_importance_data = True
        else:
            self.keep_importance_data = keep_importance_data
        self.saved_params = defaultdict(list)
        self.importances = defaultdict(list)
        self.iw_cnt = 0

    def before_backward(self, strategy, **kwargs):
        exp_counter = strategy.clock.train_exp_counter
        if exp_counter == 0:
            return

        penalty = torch.tensor(0).float().to(strategy.device)

        if self.mode == 'separate':
            for experience in range(exp_counter):
                for (_, cur_param), (_, saved_param), (_, imp) in zip(
                        strategy.model.named_parameters(),
                        self.saved_params[experience],
                        self.importances[experience]):
                    penalty += (imp * (cur_param - saved_param).pow(2)).sum()
        elif self.mode == 'online':
            prev_exp = exp_counter - 1
            for (_, cur_param), (_, saved_param), (_, imp) in zip(
                    strategy.model.named_parameters(),
                    self.saved_params[prev_exp],
                    self.importances[prev_exp]):
                penalty += (imp * (cur_param - saved_param).pow(2)).sum()
        else:
            raise ValueError('Wrong EWC mode.')

        strategy.loss_reg = self.iw_strength * penalty
        strategy.loss += strategy.loss_reg

from __future__ import absolute_import
from __future__ import division
from __future__ import print_function

import numpy as np
import random

import tensorflow as tf
from tensorflow.python.eager import context
from tensorflow.python.framework import ops
from tensorflow.python.ops import control_flow_ops
from tensorflow.python.training import optimizer

GATE_OP = 1


class PCGrad(optimizer.Optimizer):
    '''Tensorflow implementation of PCGrad.
    Gradient Surgery for Multi-Task Learning: https://arxiv.org/pdf/2001.06782.pdf
    '''

    def __init__(self, optimizer, use_locking=False, name="PCGrad"):
        """optimizer: the optimizer being wrapped
        """
        super(PCGrad, self).__init__(use_locking, name)
        self.optimizer = optimizer

    def compute_gradients(self, loss, var_list=None,
                        gate_gradients=GATE_OP,
                        aggregation_method=None,
                        colocate_gradients_with_ops=False,
                        grad_loss=None):
        assert type(loss) is list
        num_tasks = len(loss)
        loss = tf.stack(loss)
        tf.random.shuffle(loss)

        # Compute per-task gradients.
        grads_task = tf.vectorized_map(lambda x: tf.concat([tf.reshape(grad, [-1,]) 
                            for grad in tf.gradients(x, var_list) 
                            if grad is not None], axis=0), loss)

        # Compute gradient projections.
        def proj_grad(grad_task):
            for k in range(num_tasks):
                inner_product = tf.reduce_sum(grad_task*grads_task[k])
                proj_direction = inner_product / tf.reduce_sum(grads_task[k]*grads_task[k])
                grad_task = grad_task - tf.minimum(proj_direction, 0.) * grads_task[k]
            return grad_task

        proj_grads_flatten = tf.vectorized_map(proj_grad, grads_task)

        # Unpack flattened projected gradients back to their original shapes.
        proj_grads = []
        for j in range(num_tasks):
            start_idx = 0
            for idx, var in enumerate(var_list):
                grad_shape = var.get_shape()
                flatten_dim = np.prod([grad_shape.dims[i].value for i in range(len(grad_shape.dims))])
                proj_grad = proj_grads_flatten[j][start_idx:start_idx+flatten_dim]
                proj_grad = tf.reshape(proj_grad, grad_shape)
                if len(proj_grads) < len(var_list):
                    proj_grads.append(proj_grad)
                else:
                    proj_grads[idx] += proj_grad               
                start_idx += flatten_dim
        grads_and_vars = list(zip(proj_grads, var_list))
        return grads_and_vars

    def _create_slots(self, var_list):
        self.optimizer._create_slots(var_list)

    def _prepare(self):
        self.optimizer._prepare()

    def _apply_dense(self, grad, var):
        return self.optimizer._apply_dense(grad, var)

    def _resource_apply_dense(self, grad, var):
        return self.optimizer._resource_apply_dense(grad, var)

    def _apply_sparse_shared(self, grad, var, indices, scatter_add):
        return self.optimizer._apply_sparse_shared(grad, var, indices, scatter_add)

    def _apply_sparse(self, grad, var):
        return self.optimizer._apply_sparse(grad, var)

    def _resource_scatter_add(self, x, i, v):
        return self.optimizer._resource_scatter_add(x, i, v)

    def _resource_apply_sparse(self, grad, var, indices):
        return self.optimizer._resource_apply_sparse(grad, var, indices)

    def _finish(self, update_ops, name_scope):
        return self.optimizer._finish(update_ops, name_scope)

    def _call_if_callable(self, param):
        """Call the function if param is callable."""
        return param() if callable(param) else param

experimental_design.experiment_code:
# Predictive Task Scheduling (PTS) – Reference Implementation
# - Implements Experiments 1–3 described in New Methods and Experiment Strategy
# - PyTorch only for DL; uses torchvision/timm for models and datasets
# - Includes surrogate signals (Fi/Gi/Mi), meta-MLP scorer ω, beam-search scheduler
# - Saves publication-ready PDF plots; prints clear summaries to stdout
# - Includes a quick test to verify functionality and plotting

import os
import time
import math
import json
import random
from dataclasses import dataclass
from typing import List, Tuple, Dict, Optional

import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.data import DataLoader, Subset
import torchvision as tv
from torchvision import transforms

# Optional: timm for Experiment 2 (scaling)
try:
    import timm
except Exception:
    timm = None

# Optional: sklearn for APD-like ordering (clustering)
try:
    from sklearn.cluster import KMeans
except Exception:
    KMeans = None

# Plotting
import matplotlib
matplotlib.use("Agg")  # headless-safe
import matplotlib.pyplot as plt
import seaborn as sns

# ------------------------
# Utilities & Metrics
# ------------------------

def set_seed(seed=42):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)
    torch.backends.cudnn.deterministic = True
    torch.backends.cudnn.benchmark = False


def device_default():
    return 'cuda' if torch.cuda.is_available() else 'cpu'


@dataclass
class RunMetrics:
    avg_acc: float
    avg_forgetting: float
    min_acc: float
    wc_acc: float
    time_min: float
    order: List[int]


class AverageMeter:
    def __init__(self):
        self.sum = 0.0
        self.n = 0
    def update(self, val, n=1):
        self.sum += float(val) * n
        self.n += n
    @property
    def avg(self):
        return self.sum / max(1, self.n)


# ------------------------
# Datasets & Task Streams
# ------------------------

class RotatedMNIST(torch.utils.data.Dataset):
    def __init__(self, base, angle):
        self.base = base
        self.angle = angle
        self.rotate = transforms.RandomRotation((angle, angle))
    def __len__(self):
        return len(self.base)
    def __getitem__(self, idx):
        x, y = self.base[idx]
        x = self.rotate(x)
        if x.shape[0] == 1:  # grayscale to 3ch for CNNs expecting 3 channels
            x = x.repeat(3, 1, 1)
        return x, y


class PermutedMNIST(torch.utils.data.Dataset):
    def __init__(self, base, perm):
        self.base = base
        self.perm = perm
    def __len__(self):
        return len(self.base)
    def __getitem__(self, idx):
        x, y = self.base[idx]
        x = x.view(-1)[self.perm].view(1, 28, 28)
        x = x.repeat(3, 1, 1)
        return x, y


def get_rotated_mnist(num_tasks=20, train=True, data_root="./data"):
    tfm = transforms.ToTensor()
    base = tv.datasets.MNIST(root=data_root, train=train, download=True, transform=tfm)
    angles = np.linspace(0, 180, num_tasks)
    tasks = [RotatedMNIST(base, float(a)) for a in angles]
    return tasks


def get_permuted_mnist(num_tasks=20, train=True, data_root="./data"):
    tfm = transforms.ToTensor()
    base = tv.datasets.MNIST(root=data_root, train=train, download=True, transform=tfm)
    perms = [torch.randperm(28 * 28) for _ in range(num_tasks)]
    tasks = [PermutedMNIST(base, p) for p in perms]
    return tasks


def get_cifar100_split(num_tasks=20, classes_per_task=5, train=True, data_root="./data"):
    tfm_train = transforms.Compose([
        transforms.RandomCrop(32, padding=4),
        transforms.RandomHorizontalFlip(),
        transforms.ToTensor(),
        transforms.Normalize((0.5071, 0.4867, 0.4408), (0.2675, 0.2565, 0.2761)),
    ])
    tfm_test = transforms.Compose([
        transforms.ToTensor(),
        transforms.Normalize((0.5071, 0.4867, 0.4408), (0.2675, 0.2565, 0.2761)),
    ])
    ds = tv.datasets.CIFAR100(root=data_root, train=train, download=True, transform=(tfm_train if train else tfm_test))
    class_order = list(range(100))  # deterministic base order; can be shuffled externally
    tasks = []
    for t in range(num_tasks):
        cls = class_order[t * classes_per_task:(t + 1) * classes_per_task]
        idx = [i for i, (_, y) in enumerate(ds) if y in cls]
        tasks.append(Subset(ds, idx))
    return tasks


# ------------------------
# Models & PEFT (LoRA)
# ------------------------

class SmallCNN(nn.Module):
    def __init__(self, in_ch=3, num_classes=10, emb_dim=128):
        super().__init__()
        self.features = nn.Sequential(
            nn.Conv2d(in_ch, 64, 3, padding=1), nn.ReLU(), nn.MaxPool2d(2),
            nn.Conv2d(64, 128, 3, padding=1), nn.ReLU(), nn.MaxPool2d(2),
            nn.Conv2d(128, 256, 3, padding=1), nn.ReLU(), nn.AdaptiveAvgPool2d(1)
        )
        self.flatten = nn.Flatten()
        self.proj = nn.Linear(256, emb_dim)
        self.head = nn.Linear(emb_dim, num_classes)
    def forward(self, x, return_embed=False):
        z = self.features(x)
        z = self.flatten(z)
        e = self.proj(z)
        h = F.relu(e)
        out = self.head(h)
        if return_embed:
            return out, e
        return out


class LoRALinear(nn.Module):
    def __init__(self, base: nn.Linear, rank=8, scale=1.0):
        super().__init__()
        self.base = base
        in_f, out_f = base.in_features, base.out_features
        self.A = nn.Parameter(torch.zeros(rank, in_f))
        self.B = nn.Parameter(torch.zeros(out_f, rank))
        nn.init.kaiming_uniform_(self.A, a=math.sqrt(5))
        nn.init.zeros_(self.B)
        self.scale = scale
        for p in self.base.parameters():
            p.requires_grad = False
    def forward(self, x):
        return self.base(x) + self.scale * (x @ self.A.t() @ self.B.t())


class PEFTWrapper(nn.Module):
    def __init__(self, backbone: nn.Module, lora_rank=8):
        super().__init__()
        self.backbone = backbone
        # replace classifier head if linear
        target = None
        if hasattr(self.backbone, 'head') and isinstance(self.backbone.head, nn.Linear):
            target = ('head', self.backbone.head)
        elif hasattr(self.backbone, 'classifier') and isinstance(self.backbone.classifier, nn.Linear):
            target = ('classifier', self.backbone.classifier)
        else:
            # fallback: last Linear in modules
            last_name, last_mod = None, None
            for n, m in self.backbone.named_modules():
                if isinstance(m, nn.Linear):
                    last_name, last_mod = n, m
            if last_mod is not None:
                target = (last_name, last_mod)
        if target is not None:
            name, mod = target
            # navigate parent
            parent = self.backbone
            parts = name.split('.')
            for p in parts[:-1]:
                parent = getattr(parent, p)
            setattr(parent, parts[-1], LoRALinear(mod, rank=lora_rank))
        # freeze all except LoRA params
        for n, p in self.backbone.named_parameters():
            if ('.A' in n) or ('.B' in n):
                p.requires_grad = True
            else:
                p.requires_grad = False
    def forward(self, x, return_embed=False):
        # assumes backbone supports return_embed if SmallCNN; otherwise return only logits
        if return_embed:
            return self.backbone(x, return_embed=True)
        return self.backbone(x)


# ------------------------
# Surrogate computations Fi/Gi/Mi
# ------------------------

@torch.no_grad()
def compute_embeddings(model, loader, device, max_samples=32):
    model.eval()
    embs, ys = [], []
    n = 0
    for x, y in loader:
        x = x.to(device)
        out, e = model(x, return_embed=True)
        embs.append(e.detach().cpu())
        ys.append(y)
        n += x.size(0)
        if n >= max_samples:
            break
    if len(embs) == 0:
        return torch.zeros(1, 16), torch.zeros(1, dtype=torch.long)
    return torch.cat(embs, 0), torch.cat(ys, 0)


@torch.no_grad()
def linear_cka(X, Y):
    # X, Y: (n,d)
    if X is None or Y is None or X.numel() == 0 or Y.numel() == 0:
        return 0.0
    X = X - X.mean(0, keepdim=True)
    Y = Y - Y.mean(0, keepdim=True)
    HSIC = (X.t() @ Y).pow(2).sum()
    var1 = (X.t() @ X).pow(2).sum().clamp_min(1e-8)
    var2 = (Y.t() @ Y).pow(2).sum().clamp_min(1e-8)
    return float((HSIC / (var1.sqrt() * var2.sqrt())).item())


def grad_vector(model):
    grads = []
    for p in model.parameters():
        if p.requires_grad and p.grad is not None:
            grads.append(p.grad.view(-1))
    if len(grads) == 0:
        # no grads yet -> return empty tensor on CPU
        return torch.tensor([])
    return torch.cat(grads)


@torch.no_grad()
def cosine(u, v):
    if u.numel() == 0 or v.numel() == 0:
        return torch.tensor(0.0)
    return F.cosine_similarity(u, v, dim=0).clamp(-1, 1)


def compute_grad_conflict(model, device, cand_loader, anchor_loader, criterion):
    model.train()  # need grads
    try:
        x_c, y_c = next(iter(cand_loader))
    except StopIteration:
        return 0.0
    x_c, y_c = x_c.to(device), y_c.to(device)
    model.zero_grad(set_to_none=True)
    out_c = model(x_c)
    loss_c = criterion(out_c, y_c)
    loss_c.backward()
    g_c = grad_vector(model).detach().cpu()

    try:
        x_a, y_a = next(iter(anchor_loader))
    except StopIteration:
        return 0.0
    x_a, y_a = x_a.to(device), y_a.to(device)
    model.zero_grad(set_to_none=True)
    out_a = model(x_a)
    loss_a = criterion(out_a, y_a)
    loss_a.backward()
    g_a = grad_vector(model).detach().cpu()
    return float(cosine(g_c, g_a).item())


def compute_lmc_loss(model, device, cand_loader, anchor_loader, criterion, lr=1e-2):
    model.train()  # need grads
    try:
        x_c, y_c = next(iter(cand_loader))
    except StopIteration:
        return 0.0
    x_c, y_c = x_c.to(device), y_c.to(device)
    model.zero_grad(set_to_none=True)
    out_c = model(x_c)
    loss_c = criterion(out_c, y_c)
    loss_c.backward()
    step = {}
    for n, p in model.named_parameters():
        if p.requires_grad and p.grad is not None:
            step[n] = -lr * p.grad.detach().clone()
    with torch.no_grad():
        base = {n: p.data.clone() for n, p in model.named_parameters() if p.requires_grad}
    alphas = [0.0, 0.5, 1.0]
    losses = []
    for a in alphas:
        with torch.no_grad():
            for n, p in model.named_parameters():
                if p.requires_grad and n in step:
                    p.data = base[n] + a * step[n]
        try:
            x_a, y_a = next(iter(anchor_loader))
        except StopIteration:
            l = 0.0
        else:
            x_a, y_a = x_a.to(device), y_a.to(device)
            with torch.no_grad():
                l = float(criterion(model(x_a), y_a).item())
        losses.append(l)
    with torch.no_grad():
        for n, p in model.named_parameters():
            if p.requires_grad and n in base:
                p.data = base[n]
    return float(np.mean(losses))


def compute_surrogates(model, device, cand_loader, anchor_loader, rb_embeds, criterion):
    # Fi
    with torch.no_grad():
        E_c, _ = compute_embeddings(model, cand_loader, device)
    Fi = linear_cka(rb_embeds, E_c) if rb_embeds is not None else 0.0
    # Gi
    Gi = compute_grad_conflict(model, device, cand_loader, anchor_loader, criterion)
    # Mi
    Mi = compute_lmc_loss(model, device, cand_loader, anchor_loader, criterion)
    return float(Fi), float(Gi), float(Mi)


# ------------------------
# Meta-MLP scorer ω and PTS Scheduler
# ------------------------

class MetaMLP(nn.Module):
    def __init__(self, d_in=4, hidden=16):
        super().__init__()
        self.net = nn.Sequential(nn.Linear(d_in, hidden), nn.ReLU(), nn.Linear(hidden, 1))
    def forward(self, x):
        return self.net(x).squeeze(-1)


def train_meta_mlp(train_data: List[Tuple[np.ndarray, float]], val_data: List[Tuple[np.ndarray, float]], epochs=20, lr=1e-3, device='cpu'):
    model = MetaMLP().to(device)
    opt = torch.optim.Adam(model.parameters(), lr=lr)
    def to_batch(data):
        X = torch.tensor(np.stack([d[0] for d in data], axis=0), dtype=torch.float32).to(device)
        y = torch.tensor([d[1] for d in data], dtype=torch.float32).to(device)
        return X, y
    Xtr, ytr = to_batch(train_data)
    Xva, yva = to_batch(val_data)
    best = 1e9
    best_state = None
    for e in range(epochs):
        model.train()
        opt.zero_grad()
        pred = model(Xtr)
        loss = F.mse_loss(pred, ytr)
        loss.backward()
        opt.step()
        model.eval()
        with torch.no_grad():
            v = F.mse_loss(model(Xva), yva).item()
        if v < best:
            best = v
            best_state = {k: v_.detach().cpu().clone() for k, v_ in model.state_dict().items()}
        # print(f"[meta] epoch {e} train {loss.item():.4f} val {v:.4f}")
    if best_state is not None:
        model.load_state_dict(best_state)
    return model


class PTSScheduler:
    def __init__(self, omega: MetaMLP, K=5, D=None, device='cpu'):
        self.omega = omega.eval().to(device)
        self.K = K
        self.D = K if D is None else D
        self.device = device
    @torch.no_grad()
    def score(self, feat):
        x = torch.tensor(feat, dtype=torch.float32, device=self.device).unsqueeze(0)
        return float(self.omega(x).item())
    @torch.no_grad()
    def select_next(self, buffer_feats: List[Tuple[int, np.ndarray]]):
        items = buffer_feats[:self.K]
        beams = [([], 0.0)]
        for depth in range(self.D):
            new_beams = []
            for seq, sc in beams:
                used = set(seq)
                for tid, feat in items:
                    if tid in used:
                        continue
                    s = self.score(feat)
                    new_beams.append((seq + [tid], sc + s))
            if not new_beams:
                break
            new_beams = sorted(new_beams, key=lambda x: -x[1])[:self.K]
            beams = new_beams
        return beams[0][0][0] if beams and beams[0][0] else items[0][0]


# ------------------------
# Replay Buffer for Anchors
# ------------------------

class ReplayBuffer:
    def __init__(self, anchor_size=32):
        self.anchor = {}  # task_id -> (X, Y)
        self.anchor_size = anchor_size
    def add_anchor(self, task_id, loader):
        Xs, Ys = [], []
        try:
            x, y = next(iter(loader))
            Xs.append(x)
            Ys.append(y)
        except StopIteration:
            pass
        if len(Xs) == 0:
            return
        X = torch.cat(Xs, 0)[: self.anchor_size]
        Y = torch.cat(Ys, 0)[: self.anchor_size]
        self.anchor[task_id] = (X.cpu(), Y.cpu())
    def build_anchor_loader(self, batch_size=32):
        if len(self.anchor) == 0:
            X = torch.zeros(batch_size, 3, 32, 32)
            Y = torch.zeros(batch_size, dtype=torch.long)
            ds = torch.utils.data.TensorDataset(X, Y)
            return DataLoader(ds, batch_size=batch_size, shuffle=False)
        Xs, Ys = [], []
        for (X, Y) in self.anchor.values():
            Xs.append(X)
            Ys.append(Y)
        X = torch.cat(Xs, 0)
        Y = torch.cat(Ys, 0)
        ds = torch.utils.data.TensorDataset(X, Y)
        return DataLoader(ds, batch_size=min(batch_size, len(ds)), shuffle=True)


# ------------------------
# Training & Evaluation
# ------------------------

def build_backbone(dataset_name: str, num_classes: int):
    if dataset_name.lower() in ["mnist", "permuted_mnist", "rotated_mnist"]:
        return SmallCNN(in_ch=3, num_classes=num_classes, emb_dim=128)
    elif dataset_name.lower() in ["cifar100", "imagenet100"]:
        return SmallCNN(in_ch=3, num_classes=num_classes, emb_dim=256)
    else:
        return SmallCNN(in_ch=3, num_classes=num_classes, emb_dim=256)


@torch.no_grad()
def evaluate_taskwise(model, device, task_loaders: List[DataLoader]):
    model.eval()
    accs = []
    for ld in task_loaders:
        correct = 0
        total = 0
        for x, y in ld:
            x = x.to(device)
            y = y.to(device)
            out = model(x)
            pred = out.argmax(1)
            correct += (pred == y).sum().item()
            total += y.numel()
        accs.append(100.0 * correct / max(1, total))
    return accs


def train_task(model, device, train_loader, criterion, epochs=1, lr=5e-4, log_losses: Optional[List[float]] = None):
    model.train()
    opt = torch.optim.Adam([p for p in model.parameters() if p.requires_grad], lr=lr)
    for e in range(epochs):
        for x, y in train_loader:
            x = x.to(device)
            y = y.to(device)
            opt.zero_grad(set_to_none=True)
            out = model(x)
            loss = criterion(out, y)
            loss.backward()
            opt.step()
            if log_losses is not None:
                log_losses.append(float(loss.item()))


def compute_accuracy_matrix(model, device, order: List[int], task_loaders_tr: List[DataLoader], task_loaders_te: List[DataLoader], epochs_per_task=3, lr=5e-4):
    criterion = nn.CrossEntropyLoss()
    rb = ReplayBuffer(anchor_size=32)
    rb_emb = None
    age = {}
    acc_matrix = []  # per step, per task (dense with carry-forward)
    losses = []
    for step, tid in enumerate(order):
        train_task(model, device, task_loaders_tr[tid], criterion, epochs=epochs_per_task, lr=lr, log_losses=losses)
        rb.add_anchor(tid, task_loaders_tr[tid])
        with torch.no_grad():
            e, _ = compute_embeddings(model, task_loaders_tr[tid], device)
            rb_emb = e if rb_emb is None else torch.cat([rb_emb, e], 0)[-32:]
        age[tid] = age.get(tid, 0) + 1
        # eval on all seen tasks
        seen_test_loaders = [task_loaders_te[t] for t in order[: step + 1]]
        accs = evaluate_taskwise(model, device, seen_test_loaders)
        # build dense row
        row = [0.0] * len(task_loaders_tr)
        for i, t in enumerate(order[: step + 1]):
            row[t] = accs[i]
        # carry-forward previous for unseen
        if step > 0:
            prev = acc_matrix[-1]
            for t in range(len(row)):
                if row[t] == 0.0:
                    row[t] = prev[t]
        acc_matrix.append(row)
    return np.array(acc_matrix, dtype=np.float32), losses


def compute_forgetting(acc_matrix: np.ndarray):
    # acc_matrix[s, t]
    S, T = acc_matrix.shape
    forgetting_vals = []
    for t in range(T):
        hist = [acc_matrix[s, t] for s in range(S) if acc_matrix[s, t] > 0]
        if len(hist) >= 2:
            forgetting_vals.append(max(hist[:-1]) - hist[-1])
        elif len(hist) == 1:
            forgetting_vals.append(0.0)
    avg_f = float(np.mean(forgetting_vals)) if len(forgetting_vals) else 0.0
    return avg_f, forgetting_vals


def build_confusion_matrix(model, device, all_loaders: List[DataLoader], num_classes: int):
    cm = np.zeros((num_classes, num_classes), dtype=np.int64)
    model.eval()
    with torch.no_grad():
        for ld in all_loaders:
            for x, y in ld:
                x = x.to(device)
                y = y.to(device)
                logits = model(x)
                preds = logits.argmax(1)
                for t, p in zip(y.view(-1), preds.view(-1)):
                    cm[int(t.item()), int(p.item())] += 1
    return cm


# ------------------------
# Plotting helpers (save as PDF only)
# ------------------------

def plot_training_loss(losses: List[float], fname="training_loss_pts.pdf"):
    plt.figure(figsize=(6, 4))
    plt.plot(losses, label='train loss', color='tab:blue')
    plt.xlabel('Iteration')
    plt.ylabel('Cross-entropy loss')
    plt.title('Training Loss (PTS order)')
    plt.legend()
    plt.tight_layout()
