# ------------------------
# Ordering baselines
# ------------------------

def chronological_order(T: int):
    return list(range(T))


def random_order(T: int):
    l = list(range(T))
    random.shuffle(l)
    return l


def static_similarity_order(model, device, task_loaders_tr: List[DataLoader]):
    # Greedy nearest-neighbor chaining on task centroids
    with torch.no_grad():
        cents = []
        for ld in task_loaders_tr:
            e, _ = compute_embeddings(model, ld, device)
            cents.append(F.normalize(e.mean(0, keepdim=True), dim=1))
        C = torch.cat(cents, 0)  # [T, d]
    sim = (C @ C.t()).cpu().numpy()
    T = len(task_loaders_tr)
    used = set([0])
    order = [0]
    for _ in range(T - 1):
        last = order[-1]
        cand = np.argsort(-sim[last])
        found = None
        for j in cand:
            if int(j) not in used:
                found = int(j)
                break
        order.append(found)
        used.add(found)
    return order


def apd_like_order(model, device, task_loaders_tr: List[DataLoader], n_clusters=5):
    # Simple k-means on centroids; order clusters by intra-cluster similarity then chain tasks within clusters
    if KMeans is None:
        return chronological_order(len(task_loaders_tr))
    with torch.no_grad():
        cents = []
        for ld in task_loaders_tr:
            e, _ = compute_embeddings(model, ld, device)
            cents.append(e.mean(0).cpu().numpy())
        X = np.stack(cents, 0)
    k = min(n_clusters, len(task_loaders_tr))
    labels = KMeans(n_clusters=k, n_init=5, random_state=0).fit_predict(X)
    clusters = {i: np.where(labels == i)[0].tolist() for i in range(k)}
    # order clusters by average norm (proxy for cohesion)
    cluster_scores = {}
    for i, idxs in clusters.items():
        if len(idxs) == 0:
            cluster_scores[i] = -1e9
        else:
            mu = X[idxs].mean(0, keepdims=True)
            d = ((X[idxs] - mu) ** 2).sum(1).mean()
            cluster_scores[i] = -float(d)
    cluster_order = [c for c, _ in sorted(cluster_scores.items(), key=lambda x: -x[1])]
    order = []
    for c in cluster_order:
        ids = clusters[c]
        if len(ids) == 0:
            continue
        # chain within cluster by nearest neighbor
        used = set([ids[0]])
        chain = [ids[0]]
        while len(chain) < len(ids):
            last = chain[-1]
            dists = np.linalg.norm(X[ids] - X[last], axis=1)
            perm = [ids[i] for i in np.argsort(dists)]
            for j in perm:
                if j not in used:
                    chain.append(j)
                    used.add(j)
                    break
        order += chain
    # append any missing
    for i in range(len(task_loaders_tr)):
        if i not in order:
            order.append(i)
    return order


# ------------------------
# Experiment 1: Effectiveness on Split-CIFAR100 + Ablations + Plots
# ------------------------

def experiment1(split_num_tasks=20, classes_per_task=5, epochs_per_task=3, seed=1, save_plots=True, device=None):
    device = device or device_default()
    set_seed(seed)
    print("[Exp1] Preparing Split-CIFAR100 tasks...")
    tr_tasks = get_cifar100_split(num_tasks=split_num_tasks, classes_per_task=classes_per_task, train=True)
    te_tasks = get_cifar100_split(num_tasks=split_num_tasks, classes_per_task=classes_per_task, train=False)
    task_loaders_tr = [DataLoader(t, batch_size=128, shuffle=True, num_workers=2) for t in tr_tasks]
    task_loaders_te = [DataLoader(t, batch_size=256, shuffle=False, num_workers=2) for t in te_tasks]

    model_base = PEFTWrapper(build_backbone('cifar100', num_classes=100), lora_rank=16).to(device)
    criterion = nn.CrossEntropyLoss()

    # Meta-MLP ω: train quickly on synthetic (Rotated MNIST) to avoid leakage
    print("[Exp1] Meta-MLP training on Rotated-MNIST synthetic streams (quick)...")
    rot_tr = get_rotated_mnist(num_tasks=8, train=True)
    rot_te = get_rotated_mnist(num_tasks=8, train=False)
    tmp_model = PEFTWrapper(build_backbone('mnist', num_classes=10), lora_rank=8).to(device)
    tmp_crit = nn.CrossEntropyLoss()
    rb = ReplayBuffer(anchor_size=16)
    meta_train, meta_val = [], []
    for s in range(3):
        order_stream = list(range(len(rot_tr)))
        random.shuffle(order_stream)
        rb_emb = None
        age = {}
        for i, tid in enumerate(order_stream[:6]):
            tr_ld = DataLoader(rot_tr[tid], batch_size=64, shuffle=True)
            te_ld = DataLoader(rot_te[tid], batch_size=128, shuffle=False)
            rb.add_anchor(tid, tr_ld)
            anch_ld = rb.build_anchor_loader(batch_size=16)
            with torch.no_grad():
                e, _ = compute_embeddings(tmp_model, tr_ld, device)
                rb_emb = e if rb_emb is None else torch.cat([rb_emb, e], 0)[-32:]
            Fi, Gi, Mi = compute_surrogates(tmp_model, device, tr_ld, anch_ld, rb_emb, tmp_crit)
            feat = np.array([Fi, Gi, Mi, age.get(tid, 0)], dtype=np.float32)
            # proxy ΔACC
            before = 0.0
            if i > 0:
                acc_before = evaluate_taskwise(tmp_model, device, [DataLoader(rot_te[o], batch_size=128, shuffle=False) for o in order_stream[:i]])
                before = float(np.mean(acc_before))
            train_task(tmp_model, device, tr_ld, tmp_crit, epochs=1, lr=1e-3)
            after = 0.0
            if i > 0:
                acc_after = evaluate_taskwise(tmp_model, device, [DataLoader(rot_te[o], batch_size=128, shuffle=False) for o in order_stream[:i]])
                after = float(np.mean(acc_after))
            delta = before - after
            (meta_train if s < 2 else meta_val).append((feat, delta))
            age[tid] = age.get(tid, 0) + 1
    omega = train_meta_mlp(meta_train, meta_val, epochs=20, lr=1e-3, device=device)

    methods = ['chrono', 'random', 'static_sim', 'apd_like', 'pts']
    results: Dict[str, RunMetrics] = {}
    acc_mats_for_plot: Dict[str, np.ndarray] = {}

    # Precompute centroids for similarity ordering using an untrained copy to avoid leakage
    with torch.no_grad():
        cents = []
        for ld in task_loaders_tr:
            e, _ = compute_embeddings(model_base, ld, device)
            cents.append(e.mean(0, keepdim=True))
        _ = cents  # not used directly here; ordering computed per method below

    for method in methods:
        print(f"[Exp1] Running method: {method}")
        model = PEFTWrapper(build_backbone('cifar100', num_classes=100), lora_rank=16).to(device)
        t0 = time.time()
        if method == 'chrono':
            order = chronological_order(len(task_loaders_tr))
        elif method == 'random':
            order = random_order(len(task_loaders_tr))
        elif method == 'static_sim':
            order = static_similarity_order(model_base, device, task_loaders_tr)
        elif method == 'apd_like':
            order = apd_like_order(model_base, device, task_loaders_tr, n_clusters=5)
        elif method == 'pts':
            remaining = list(range(len(task_loaders_tr)))
            order = []
            rb = ReplayBuffer(anchor_size=32)
            rb_emb = None
            age = {}
            scheduler = PTSScheduler(omega, K=5, D=5, device=device)
            while remaining:
                buf_ids = remaining[:5]
                feats = []
                anch_ld = rb.build_anchor_loader(batch_size=32)
                for tid in buf_ids:
                    Fi, Gi, Mi = compute_surrogates(model, device, task_loaders_tr[tid], anch_ld, rb_emb, criterion)
                    feats.append((tid, np.array([Fi, Gi, Mi, age.get(tid, 0)], dtype=np.float32)))
                pick = scheduler.select_next(feats)
                order.append(pick)
                remaining.remove(pick)
        else:
            raise ValueError(method)

        # Train sequentially and evaluate
        A, losses = compute_accuracy_matrix(
            model, device, order, task_loaders_tr, task_loaders_te, epochs_per_task=epochs_per_task, lr=5e-4
        )
        S, T = A.shape
        final = A[-1]
        avg_acc = float(np.mean([a for a in final if a > 0]))
        avg_f, f_list = compute_forgetting(A)
        min_acc = float(np.min([a for a in final if a > 0])) if any(final > 0) else 0.0
        wc_acc = float(np.min(A[:S]))
        tm = (time.time() - t0) / 60.0
        results[method] = RunMetrics(avg_acc, avg_f, min_acc, wc_acc, tm, order)
        acc_mats_for_plot[method] = A
        print(f"[Exp1][{method}] avg_acc={avg_acc:.2f} avg_forgetting={avg_f:.2f} min_acc={min_acc:.2f} wc_acc={wc_acc:.2f} time_min={tm:.2f}")

        # Save plots for PTS only (to avoid too many files) and for comparison curves
        if save_plots and method == 'pts':
            plot_training_loss(losses, fname="training_loss_pts.pdf")
            plot_forgetting(f_list, fname="forgetting_pts.pdf")
            # Confusion on all test loaders (here: 100 classes)
            cm = build_confusion_matrix(model, device, [ld for ld in task_loaders_te], num_classes=100)
            plot_confusion(cm, fname="confusion_matrix_pts.pdf")

    # Comparison accuracy curves
    if save_plots:
        plot_accuracy_curves({k: v for k, v in acc_mats_for_plot.items() if k in ['chrono', 'random', 'pts']}, fname="accuracy_pts_vs_baselines.pdf")

    print("[Exp1] Summary:")
    print(json.dumps({m: results[m].__dict__ for m in results}, indent=2))
    return results


# ------------------------
# Experiment 2: Scaling & Overhead (ViT if available) + Overhead Plot
# ------------------------

def experiment2_scaling_overhead(tasks=10, classes_per_task=10, epochs_per_task=2, seed=1, save_plots=True, device=None):
    device = device or device_default()
    set_seed(seed)
    print("[Exp2] Scaling & Overhead experiment")
    use_vit = timm is not None
    if use_vit:
        print("[Exp2] Using timm ViT-B/16 (pretrained) with LoRA head surrogate")
        backbone = timm.create_model('vit_base_patch16_224', pretrained=True, num_classes=100)
        model = PEFTWrapper(backbone, lora_rank=16).to(device)
        # Data: CIFAR100 resized to 224 as ImageNet-100 surrogate (10×10 classes)
        tfm_tr = transforms.Compose([
            transforms.Resize(224), transforms.RandomResizedCrop(224, scale=(0.5, 1.0)), transforms.RandomHorizontalFlip(),
            transforms.ToTensor(), transforms.Normalize((0.485, 0.456, 0.406), (0.229, 0.224, 0.225)),
        ])
        tfm_te = transforms.Compose([
            transforms.Resize(224), transforms.CenterCrop(224), transforms.ToTensor(),
            transforms.Normalize((0.485, 0.456, 0.406), (0.229, 0.224, 0.225)),
        ])
        ds_tr = tv.datasets.CIFAR100('./data', train=True, download=True, transform=tfm_tr)
        ds_te = tv.datasets.CIFAR100('./data', train=False, download=True, transform=tfm_te)
    else:
        print("[Exp2] timm not available; falling back to SmallCNN proxy (still measures overhead)")
        model = PEFTWrapper(build_backbone('cifar100', num_classes=100), lora_rank=16).to(device)
        ds_tr = tv.datasets.CIFAR100('./data', train=True, download=True, transform=transforms.Compose([
            transforms.RandomCrop(32, padding=4), transforms.RandomHorizontalFlip(), transforms.ToTensor(),
            transforms.Normalize((0.5071, 0.4867, 0.4408), (0.2675, 0.2565, 0.2761)),
        ]))
        ds_te = tv.datasets.CIFAR100('./data', train=False, download=True, transform=transforms.Compose([
            transforms.ToTensor(), transforms.Normalize((0.5071, 0.4867, 0.4408), (0.2675, 0.2565, 0.2761)),
        ]))

    # Split into tasks
    class_order = list(range(100))
    tasks_tr, tasks_te = [], []
    for t in range(tasks):
        cls = class_order[t * classes_per_task:(t + 1) * classes_per_task]
        idx_tr = [i for i, (_, y) in enumerate(ds_tr) if y in cls]
        idx_te = [i for i, (_, y) in enumerate(ds_te) if y in cls]
        tasks_tr.append(Subset(ds_tr, idx_tr))
        tasks_te.append(Subset(ds_te, idx_te))
    ldr_tr = [DataLoader(t, batch_size=64, shuffle=True, num_workers=2) for t in tasks_tr]
    ldr_te = [DataLoader(t, batch_size=128, shuffle=False, num_workers=2) for t in tasks_te]

    criterion = nn.CrossEntropyLoss()

    # Simple ω (random-initialized for overhead; plug in trained ω from Exp1 for effectiveness)
    omega = MetaMLP().to(device)
    scheduler = PTSScheduler(omega, K=5, D=5, device=device)

    # Measure surrogate time vs training time
    rb = ReplayBuffer(anchor_size=32)
    rb_emb = None
    age = {}
    remaining = list(range(tasks))
    order = []
    total_sur_t = 0.0
    total_train_t = 0.0
    criterion = nn.CrossEntropyLoss()

    while remaining:
        buf_ids = remaining[:5]
        feats = []
        anch_ld = rb.build_anchor_loader(batch_size=32)
        t0 = time.time()
        for tid in buf_ids:
            Fi, Gi, Mi = compute_surrogates(model, device, ldr_tr[tid], anch_ld, rb_emb, criterion)
            feats.append((tid, np.array([Fi, Gi, Mi, age.get(tid, 0)], dtype=np.float32)))
        total_sur_t += (time.time() - t0)
        pick = scheduler.select_next(feats)
        order.append(pick)
        remaining.remove(pick)
        # one short epoch for timing (few batches)
        t1 = time.time()
        model.train()
        opt = torch.optim.Adam([p for p in model.parameters() if p.requires_grad], lr=1e-4)
        for i, (x, y) in enumerate(ldr_tr[pick]):
            x = x.to(device)
            y = y.to(device)
            opt.zero_grad(set_to_none=True)
            loss = criterion(model(x), y)
            loss.backward()
            opt.step()
            if i >= 5:  # limit iterations to keep this lightweight
                break
        total_train_t += (time.time() - t1)
        rb.add_anchor(pick, ldr_tr[pick])
        with torch.no_grad():
            e, _ = compute_embeddings(model, ldr_tr[pick], device)
            rb_emb = e if rb_emb is None else torch.cat([rb_emb, e], 0)[-32:]
        age[pick] = age.get(pick, 0) + 1

    overhead_pct = 100.0 * total_sur_t / max(1e-6, total_train_t)
    print(f"[Exp2] Order chosen by PTS: {order}")
    print(f"[Exp2] Surrogate time: {total_sur_t:.2f}s, Training time(sampled): {total_train_t:.2f}s, Overhead: {overhead_pct:.2f}%")

    if save_plots:
        plot_overhead_bars({"pts_overhead": overhead_pct, "chrono_baseline_overhead": 0.0}, fname="overhead_pts.pdf")

    # Quick effectiveness check: train very briefly in the planned order vs chrono
    def train_eval(order_train):
        m = PEFTWrapper(build_backbone('cifar100', num_classes=100), lora_rank=16).to(device) if not use_vit else PEFTWrapper(timm.create_model('vit_base_patch16_224', pretrained=True, num_classes=100), lora_rank=16).to(device)
        for tid in order_train:
            train_task(m, device, ldr_tr[tid], criterion, epochs=epochs_per_task, lr=1e-4)
        accs = evaluate_taskwise(m, device, ldr_te)
        return float(np.mean(accs)), float(np.min(accs))

    avg_pts, min_pts = train_eval(order)
    avg_chr, min_chr = train_eval(list(range(tasks)))
    print(f"[Exp2] ACC(min) – PTS: {avg_pts:.2f} ({min_pts:.2f}) vs Chrono: {avg_chr:.2f} ({min_chr:.2f})")

    return {"overhead_pct": overhead_pct, "avg_acc_pts": avg_pts, "min_acc_pts": min_pts, "avg_acc_chrono": avg_chr, "min_acc_chrono": min_chr, "order": order}


# ------------------------
# Experiment 3: Robustness (Task Injection + Data Sparsity)
# ------------------------

def experiment3_robustness(num_tasks=12, epochs_per_task=2, seed=1, save_plots=True, device=None):
    device = device or device_default()
    set_seed(seed)
    print("[Exp3] Robustness experiment with Permuted-MNIST (injected adversarial task + sparsity)")
    tasks_tr = get_permuted_mnist(num_tasks=num_tasks, train=True)
    tasks_te = get_permuted_mnist(num_tasks=num_tasks, train=False)
    ldr_tr = [DataLoader(t, batch_size=128, shuffle=True) for t in tasks_tr]
    ldr_te = [DataLoader(t, batch_size=256, shuffle=False) for t in tasks_te]

    criterion = nn.CrossEntropyLoss()
    omega = MetaMLP().to(device)
    scheduler = PTSScheduler(omega, K=4, D=4, device=device)

    # Choose adversarially dissimilar task (low affinity to task 0)
    probe_model = PEFTWrapper(build_backbone('mnist', num_classes=10), lora_rank=8).to(device)
    with torch.no_grad():
        E0, _ = compute_embeddings(probe_model, ldr_tr[0], device)
        c0 = F.normalize(E0.mean(0, keepdim=True), dim=1)
        sims = []
        for i in range(num_tasks):
            Ei, _ = compute_embeddings(probe_model, ldr_tr[i], device)
            ci = F.normalize(Ei.mean(0, keepdim=True), dim=1)
            s = float((c0 @ ci.t()).item())
            sims.append((i, s))
    inj_task = sorted(sims, key=lambda x: x[1])[0][0]
    inj_pos = min(3, num_tasks - 1)

    def run_once(method='pts', subsample=1.0):
        m = PEFTWrapper(build_backbone('mnist', num_classes=10), lora_rank=8).to(device)
        # subsample data for sparsity
        tr_sub = []
        for ld in ldr_tr:
            try:
                xb, yb = next(iter(ld))
            except StopIteration:
                xb = torch.zeros(8, 3, 28, 28)
                yb = torch.zeros(8, dtype=torch.long)
            n = max(1, int(xb.size(0) * subsample))
            ds = torch.utils.data.TensorDataset(xb[:n], yb[:n])
            tr_sub.append(DataLoader(ds, batch_size=64, shuffle=True))
        base_order = list(range(num_tasks))
        base_order.remove(inj_task)
        base_order.insert(inj_pos, inj_task)
        order = base_order.copy()
        rb = ReplayBuffer(anchor_size=16)
        rb_emb = None
        age = {}
        if method == 'pts':
            rem = order.copy()
            order = []
            while rem:
                buf_ids = rem[:4]
                feats = []
                anch_ld = rb.build_anchor_loader(batch_size=16)
                for tid in buf_ids:
                    Fi, Gi, Mi = compute_surrogates(m, device, tr_sub[tid], anch_ld, rb_emb, criterion)
                    feats.append((tid, np.array([Fi, Gi, Mi, age.get(tid, 0)], dtype=np.float32)))
                pick = scheduler.select_next(feats)
                order.append(pick)
                rem.remove(pick)
        elif method == 'random':
            random.shuffle(order)
        # chrono uses base injected order as-is
        acc_curve = []
        for tid in order:
            train_task(m, device, tr_sub[tid], criterion, epochs=epochs_per_task, lr=1e-3)
            rb.add_anchor(tid, tr_sub[tid])
            with torch.no_grad():
                e, _ = compute_embeddings(m, tr_sub[tid], device)
                rb_emb = e if rb_emb is None else torch.cat([rb_emb, e], 0)[-32:]
            # mean acc over all tasks
            acc_curve.append(float(np.mean(evaluate_taskwise(m, device, ldr_te))))
        # TTR
        inj_idx = order.index(inj_task)
        pre_acc = acc_curve[inj_idx - 1] if inj_idx > 0 else acc_curve[0]
        ttr = None
        for k in range(inj_idx, len(acc_curve)):
            if acc_curve[k] >= pre_acc - 0.2:
                ttr = k - inj_idx
                break
        return order, acc_curve, ttr

    out = {}
    for method in ['chrono', 'random', 'pts']:
        order, curve, ttr = run_once(method=method, subsample=1.0)
        out[method] = {"order": order, "final_acc": float(curve[-1]), "wc_acc": float(min(curve)), "ttr": (int(ttr) if ttr is not None else None)}
        print(f"[Exp3][{method}] final_acc={out[method]['final_acc']:.2f} wc_acc={out[method]['wc_acc']:.2f} TTR={out[method]['ttr']} order={order}")

    # Sparsity: 10% data
    sparse = {}
    for method in ['chrono', 'pts']:
        _, curve, _ = run_once(method=method, subsample=0.1)
        sparse[method] = {"final_acc": float(curve[-1]), "wc_acc": float(min(curve))}
        print(f"[Exp3][sparse {method}] final_acc={sparse[method]['final_acc']:.2f} wc_acc={sparse[method]['wc_acc']:.2f}")

    if save_plots:
        # Plot only PTS curve
        _, pts_curve, _ = run_once(method='pts', subsample=1.0)
        plt.figure(figsize=(6, 4))
        plt.plot(pts_curve, label='PTS', color='tab:green')
        plt.axvline(x=inj_pos, color='tab:red', linestyle='--', label='Injected task')
        plt.xlabel('Task step')
        plt.ylabel('Mean ACC over all tasks (%)')
        plt.title('Robustness under task injection')
        plt.legend()
        plt.tight_layout()
        plt.savefig("accuracy_robustness_pts.pdf", bbox_inches='tight')
        plt.close()

    return out, sparse


